con:config.script:
//----------------------------------------------------------
// INIT "FOR WAITING AND RETURN EVENT TYPE" USAGE
//----------------------------------------------------------
// !!! make sure RunTestStep Run Mode is set to (Run primary TestCase)

// init own properties
String my_properties_step_name = "Properties"
def properties = testRunner.testCase.getTestStepByName(my_properties_step_name);
properties.setPropertyValue("eventType", "")
properties.setPropertyValue("passedSessionID", "")

// init waiting test case
def suite = testRunner.testCase.testSuite
def target_case = suite.getTestCaseByName("waitingAndReturnEventType")
def target_properties = target_case.getTestStepByName("Properties")
// set Properties
target_properties.setPropertyValue("target_name",testRunner.testCase.getLabel())
target_properties.setPropertyValue("target_step",my_properties_step_name)

// read the file
def properties = new java.util.Properties();
properties.load( new java.io.FileInputStream( "etc/soapui/testdata.properties" ));
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );

// assign all properties
def names = properties.propertyNames();
while (names.hasMoreElements()) {
   def name = names.nextElement();
   targetStep.setPropertyValue(name, properties.getProperty(name));
   //log.info "Property (" + name + ", " + properties.getProperty(name) + ") set."
}

log.info "Update done."

def today = new Date();
def formatedDay = String.format('%tY-%<tm-%<td', today);
def formatedTime = String.format('%tH:%<tM:%<tS', today);
def formatedToday = formatedDay + " " + formatedTime;
def sendersTime = "sendersTime";
def geoTime = "geoTime";

// set property
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
targetStep.setPropertyValue( sendersTime, formatedToday);
targetStep.setPropertyValue( geoTime, formatedToday);

con:configuration.scriptText:
def groovyUtils = new com.eviware.soapui.support.GroovyUtils( context )
def holder = groovyUtils.getXmlHolder( messageExchange.responseContent )

assert holder["//ns1:MOPEventStatus/code"] == "10000"

con:response.con:script:
log.info("waiting von reconnect")

// setup
def runner = context.getTestRunner()

// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)
def properties = runner.testCase.getTestStepByName("Properties")

// get eventType out of request
def eventType = holder.getNodeValue("//*:eventType")
def requestID = holder.getNodeValue("//*:sessionID")
log.info("eventType: " + eventType + ", sessionID: " + requestID)

// filter by sessionID + eventType
def curr_ID = properties.getPropertyValue("curr_sessionID")
if(eventType == "readyForOperation"){
	log.info("readyForOperation")
	runner.gotoStepByName("End")
}else if(eventType == "loginRequired"){
	log.info("loginRequired")
	runner.gotoStepByName("Run login9010")
}else if(curr_ID == requestID){
	log.info("session OK")
	runner.gotoStepByName("waitingAndReturnEventType")
}else{
	throw new Exception( "Error in TestStep: waiting" );
}

