con:config.script:
// init
def properties = testRunner.testCase.getTestStepByName("Properties");
def eventType = properties.getPropertyValue("eventType")
String wantedType = "readyForOperation"
String wantedSession = properties.getPropertyValue("curr_sessionID")
String sessionID = properties.getPropertyValue("passedSessionID")

log.info("after eventType, wantedSession, sessionID are:" + eventType + ", " + wantedSession + ", " + sessionID)
if(eventType != wantedType && sessionID == wantedSession){
	//log.info("once again")
	testRunner.gotoStepByName("waitingAndReturnEventType")

}

con:response.con:script:
def runner = context.getTestRunner()
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context);
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent);
def properties = runner.testCase.getTestStepByName("Properties")

// get eventType out of request
def eventType = holder.getNodeValue("//*:eventType")
def requestID = holder.getNodeValue("//*:sessionID")
log.info("--reconnect: incoming request arrived: "+ eventType +"--")

// filter by sessionID + eventType
def curr_ID = properties.getPropertyValue("curr_sessionID")
switch (eventType){
	case "loginRequired":
		log.info("loginRequired")
		runner.gotoStepByName("Run login9010")
		break
	case "readyForOperation":
		if (curr_ID == requestID){
			log.info("readyForOperation")
			runner.gotoStepByName("End")
		}else{
			log.info("readyForOperation BUT wrongSession")
		}
		break
	default:
		if (curr_ID == requestID){
			// possible orderData*
			log.info("other eventType")
			runner.gotoStepByName("waitingAndReturnEventType")
		}else{
			log.info("other eventType BUT wrongSession")
		}
		break
}

