//----------------------------------------------------------
// INIT "FOR WAITING AND RETURN EVENT TYPE" USAGE
//----------------------------------------------------------
// !!! make sure RunTestStep Run Mode is set to (Run primary TestCase)

// init own properties
String my_properties_step_name = "Store Properties"
def properties = testRunner.testCase.getTestStepByName(my_properties_step_name);
properties.setPropertyValue("eventType", "")
properties.setPropertyValue("passedSessionID", "")

// init waiting test case
def suite = testRunner.testCase.testSuite
def target_case = suite.getTestCaseByName("waitingAndReturnEventType")
def target_properties = target_case.getTestStepByName("Properties")
// set Properties
target_properties.setPropertyValue("target_name",testRunner.testCase.getLabel())
target_properties.setPropertyValue("target_step",my_properties_step_name)

// read the file
