con:response.con:script:
log.info("waiting setup")

// setup
def runner = context.getTestRunner()

// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)
def properties = runner.testCase.getTestStepByName("Store Properties")

// get eventType out of request
def eventType = holder.getNodeValue("//*:eventType")
def requestID = holder.getNodeValue("//*:sessionID")
log.info("eventType: " + eventType + ", sessionID: " + requestID)

// filter by sessionID + eventType
def curr_ID = properties.getPropertyValue("curr_sessionID")
if (curr_ID == requestID && eventType == "setup"){
	log.info("correctSession end eventType")
	// transfer Requesstfields to properties
	def DataFields = ['pdaUserSignatureMissing','truckLabel', 'pdaUserNo'] as String[]
	for (field in DataFields){
		path = "//*:LOGONEvent.LOGONDataField[*:name='" + field + "']/*:value"
		temp = holder.getNodeValue(path)
		//log.info(field + ": " + temp)
		properties.setPropertyValue(field, temp)
	}
	// signature missing?
	if (properties.getPropertyValue("pdaUserSignatureMissing") == "true"){
		log.info("pdaUserSignature is Missing")
		runner.gotoStepByName("signature")
	}else{
		log.info("pdaUserSignature is NOT Missing")
		runner.gotoStepByName("useTruckComposition")
	}	
}else{
	log.info("wrong sessionID or eventType")
}

