com.eviware.soapui.support.ClasspathHacker.addURL( new URL("file:///share/java/jpository/oracle/product/10.2.0.4.0/jdbc/lib/ojdbc14.jar") )
import groovy.sql.Sql

// Connection
def sql = Sql.newInstance("jdbc:oracle:thin:@adnorahu01.bp.adnovum.hu:50000:DHULGN01",
                          "ulgn01", "ulgn01", "oracle.jdbc.driver.OracleDriver")

def properties = testRunner.testCase.getTestStepByName("Properties")
def rfidIdentity = properties.getPropertyValue("rfidTagIdentity")
def rfidLabel = properties.getPropertyValue("rfidTagLabel")

def query = "SELECT rfo.rfidobject_type_cd, rfo.object_label FROM tlgnc_rfidtag rt join tlgnc_rfidobject rfo on rfo.rfidobject_id = rt.rfidobject_id WHERE rt.rfid_identity = ${rfidIdentity} AND rt.name like ${rfidLabel}"

String type = sql.firstRow(query).rfidobject_type_cd.toString()
String object_label = sql.firstRow(query).object_label.toString()

String expected_type = properties.getPropertyValue("rfidObjectType")
String expected_label = properties.getPropertyValue("rfidObjectLabel")
// assert result
if(type != expected_type){
	throw new Exception( "wrong type" );
}
if(object_label != expected_label){
	throw new Exception( "wrong object_label" );
}

/* ************************************* adminRFID2 ************************************* Test Setting: rfidObject in DB (RFIDOBJECT_ID = 2620) rfidtag not in DB (RFIDTAG_IDENTITY = "dd12ee34ff +${rfidTagNEW_ID} RFIDTAG_NAME = "sUITe2") --> Logon creates RFIDTag and sets its reference to rfidObject
!!Note: rfidTagNEW_ID in testdata.properties needs to be incremented after each test case run (this is implemented in test steps "inc rfidTagNEW_ID" and "SaveFile")
*/

// read the file
def properties = new java.util.Properties();
properties.load( new java.io.FileInputStream( "etc/soapui/testdata.properties" ));
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );

// assign all properties
def names = properties.propertyNames();
while (names.hasMoreElements()) {
   def name = names.nextElement();
   targetStep.setPropertyValue(name, properties.getProperty(name));
   //log.info "Property (" + name + ", " + properties.getProperty(name) + ") set."
}

//log.info "Update done."

def today = new Date();
def formatedDay = String.format('%tY-%<tm-%<td', today);
def formatedTime = String.format('%tH:%<tM:%<tS', today);
def formatedToday = formatedDay + " " + formatedTime;
def sendersTime = "sendersTime";
def geoTime = "geoTime";

// set property
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
targetStep.setPropertyValue( sendersTime, formatedToday);
targetStep.setPropertyValue( geoTime, formatedToday);

